"""v51 splice batch 9: Discussion paragraphs [70]-[82]."""
import io

P = 'generate_manuscript_nc.py'
lines = io.open(P, encoding='utf-8').read().split('\n')

R = []
R.append((r"p('CKI reframes transcriptomic comparison",
 r'''p('CKI reframes transcriptomic comparison\u2014from measuring absolute distance to quantifying functional divergence relative to an internal baseline\u2014but is better described as a recombination of established ideas than a conceptual shift: reference genes have long anchored normalization and quality control [29], the constrained-variance property of housekeeping genes is characterized at the genomic level [13,30], and gene-specific noise floors are central to the transcriptional-noise literature [31-33]. CKI\u2019s specific contribution is to combine these ingredients into a per-comparison, design-testable index with an explicit split-half calibration and a design-matched permutation null. The key assumption is that housekeeping (HK) genes are under stabilizing selection that constrains their expression variance across conditions. Unlike Ka/Ks\u2014where a shared mutation rate cancels mathematically\u2014CKI uses empirically defined HK genes as the baseline, lacking a comparable mechanistic cancellation, so CKI is a heuristic index rather than a formal measure of selection. The empirical calibration (mean \u03c9 = 7.70, 95% CI [7.37, 8.02]) indicates that k_f systematically exceeds k_n even for identical populations; we therefore use \u03c9_cal = \u03c9 / 7.70 as the operational scale, interpreted relative to the empirical equivalent-population distribution rather than fixed cut-offs, with the caveat that the baseline is dataset-dependent (Results).')'''))
R.append((r"p('CKI is a divergence index, not a classifier",
 r'''p('CKI is a divergence index, not a classifier\u2014and this is by design. Classifying cell types from transcriptomic data is largely a solved problem; CKI answers a complementary question: regardless of labels, how much functional divergence separates two populations, relative to their shared baseline? The negative correlation with standard metrics initially suggested complementary information content, but the decomposition analysis showed it to be partly a denominator effect, so \u03c9 is a composite of numerator and denominator information rather than a fully independent dimension. The ratio earns its increment over k_f under controlled ground truth (AUC 0.80 versus 0.72 in marrow; 0.91 versus 0.86 in skin) and in drift rejection; on real-data orderings the increment is not established, and k_f with a design-matched null remains the default for ordering claims.')'''))
R.append((r"p('CKI complements rather than replaces existing methods",
 r'''p('CKI complements rather than replaces existing methods. SAMap [35] and SATURN [4] excel at cross-species alignment and CACIMAR [36] provides conservation scoring; because these address different questions from within-species functional divergence, we did not benchmark against them quantitatively. More broadly, CKI provides a principled null model for any transcriptomic comparison: before concluding that two populations are meaningfully different, ask whether the difference exceeds baseline expectation.')'''))
R.append((r"p('We also compared CKI with Augur",
 r'''p('We also compared CKI with Augur [37], which prioritizes cell types by how predictable a condition is from single-cell expression, on the brain atlas (Supplementary Note 14). The two rankings are moderately concordant (Augur separability versus class-mean \u03c9 Spearman \u03c1 = 0.442; versus k_f \u03c1 = 0.564), and their extremes overlap (astrocytes top by \u03c9, third by Augur), so CKI is not redundant with perturbation-prioritization tools\u2014complementarity supported by the decomposition rather than by ranking correlation alone. At n = 10 classes these correlations are descriptive only; the multiclass variant and port-validation caveats are reported in Supplementary Note 14.')'''))
R.append((r"p('The pan-cancer reversal",
 r'''p('The pan-cancer reversal\u2014tumor specimens less divergent than adjacent non-tumor tissue (mean NN/TT 1.10\u20132.46, cluster-bootstrap CIs excluding 1 in four of five cancers)\u2014is a robust tissue-level observation whose mechanistic reading remains cautious: at bulk RNA-seq resolution the apparent convergence could reflect cell-composition shifts, peritumoral inflammation, or systematic RNA-quality differences rather than genuine transcriptional convergence of tumor cells. Component decomposition reinforces this caution: the reversal is predominantly a k_n effect, so the data do not indicate smaller functional divergence of tumor cells. A marker-panel composition check quantifies the confound directly (Supplementary Note 8): tumor\u2013tumor pairs show larger composition differences, and within them k_n correlates with the composition difference; however, covariate-adjusted regressions attenuate the tumor-pair coefficient by only \u22121.3% pooled (95% CI [\u22124.8%, +2.0%]). Because marker panels are noisy proxies for true composition, these attenuation estimates are lower bounds: the pooled k_n excess is not fully explained by marker-measurable composition, but neither can composition be excluded as the driver\u2014plausibly reflecting tumor-specific housekeeping dysregulation [38]\u2014and single-cell or deconvolution-based validation remains necessary. Tumor and adjacent non-tumor aliquots also differ systematically in tissue-source site and batch, and adjacent non-tumor tissue is not healthy tissue, so separating tumor-specific housekeeping elevation from field effects will require an external healthy reference. The PAM50 gradient likewise cannot be read as a functional-divergence ordering (Supplementary Note 9), and cross-dataset \u03c9 comparisons are rank-based only.')'''))
R.append((r"p('The cross-organ and cross-brain-region analyses indicate",
 r'''p('The cross-organ and cross-brain-region analyses indicate that CKI can serve as a general tool for measuring functional differentiation at multiple spatial scales, with an important qualification: the brain regional gradient is a composite signal dominated by the k_n denominator (k_n contributes 3.21-fold versus 2.03-fold from k_f), so it should not be read as a pure functional-divergence ranking. The candidate screen illustrates a second principle: 31 of the 39 Strong candidates showed raw P < 0.05 but none survived correction (minimum q = 0.520), and the raw-P enrichment is strongly tier-dependent (caveats in Supplementary Note 13)\u2014statistical claims at atlas scale require nulls that respect the experimental design, and the absence of FDR-significant signals is itself informative, delimiting what can be concluded from adult transcriptomes alone. Preliminary cross-species validation found no significant correlation of per-cell-type mean \u03c9 rankings (Spearman r = \u22120.17, P = 0.55; Supplementary Fig. 11), so cell-type-level cross-species transferability of \u03c9 remains unestablished [39].')'''))
R.append((r"p('Although no individual candidate survives FDR correction",
 r'''p('Although no individual candidate survives FDR correction, several signals are consistent with prior reports\u2014literature anchoring rather than independent validation. Maturation comparisons must be made on the k_f-only ordering, because the composite is k_n-dominated (Results): under k_f alone the lineage ranks committed OPCs highest (k_f class mean 0.197, the highest of all ten classes, though with the widest sampling uncertainty) above oligodendrocytes (0.054), with OPCs lowest (0.048)\u2014partially consistent with reports that early oligodendrocyte stages are regionally uniform whereas mature subsets become region-enriched [40,41]\u2014whereas the composite \u03c9 ordering gives the opposite picture; neither supports a monotone-maturation reading. The thalamo-temporal orientation of the mature-oligodendrocyte candidates concentrates on an axis rather than scattering across the 108 regions; a descriptive comparison against two null references (Supplementary Note 13) supports an axis concentration of the surviving candidates, whose correspondence with the developmental organization of forebrain oligodendrocytes [25] remains at the level of axis anatomy, pending lineage-tracing or spatial-transcriptomic follow-up.')'''))
R.append((r"p('CKI and standard metrics answer different questions",
 r'''p('CKI and standard metrics answer different questions, and choosing between them reduces to a few practical rules. Use CKI when the question is relative: is the functional divergence between two populations larger than what their own housekeeping baseline varies by, within the same dataset and gene-selection scheme? CKI then offers a normalized, interpretable scale, higher discrimination than raw distances for strong perturbations, and a specificity-first screen: a significant \u03c9 rejects label exchangeability under a design-matched null\u2014drift on the anchor is the null hypothesis by construction, and functional signal on the anchor is invisible to \u03c9. Before trusting fine-grained \u03c9 orderings, diagnose the denominator: if k_n lies in the extreme tail of its own null or correlates with technical covariates, report k_f with the design-matched null directly. In the real data analyzed here, \u03c9 orderings were predominantly denominator-driven (Supplementary Note 9), so k_f plus a design-matched null is the honest default for ordering claims, with \u03c9 reserved for its specificity-first property. Use standard metrics when absolute cross-dataset distances are required, for classification, for weak-to-moderate effects at atlas scale, or when the baseline itself is suspect\u2014then interpret k_n and k_f separately rather than trusting \u03c9 alone.')'''))
R.append((r"p('For prospective applications of CKI we recommend",
 r'''p('For prospective applications we recommend the following. (i) Use at least 100\u2013200 cells per group, below which pseudobulk noise inflates both k_n and k_f unpredictably. (ii) Use the pre-specified HRT Atlas v1.0 housekeeping panel (shipped with the package as cki/data/hrt_atlas.csv) rather than data-driven auto-detection. (iii) Compare populations only within the same dataset and gene-selection scheme; absolute \u03c9 does not transfer. (iv) Calibrate within the dataset of interest by split-half sampling, interpreting \u03c9 relative to that internal baseline rather than the mouse-derived 7.70. (v) Use a permutation null matching the experimental design (block-shuffle where libraries or donors define blocks; cki.blocknull.block_shuffle_test), and expect bounded sensitivity\u2014\u03c9 is a specificity-first screen whose value is rejecting neutral drift, not detecting weak functional shifts.')'''))
R.append((r"p('Limitations. Several boundaries delimit",
 r'''p('Limitations. Several boundaries delimit where \u03c9 can fire and how it should be read. (i) Scope: CKI is designed to detect state changes within a given cell type, not to discriminate cell-type identity; because the housekeeping anchor is cell-type-specific (housekeeping gene sets may differ across cell types), the k_n baseline is directly comparable only within the same cell type, so limited cross-type discrimination of \u03c9 is expected by design and delineates, rather than limits, the index\u2019s scope; the intended domain is biologically matched populations, and CKI currently operates at the pseudobulk level. (ii) Gene-set definition and calibration: the per-pair k_f scheme selects genes by the observed difference itself, so k_f magnitudes are inflated upper bounds (median 1.61-fold) and absolute tier thresholds are scheme-specific; housekeeping gene expression may be dysregulated in cancer [38]; and the empirical calibration factor (7.70, 95% CI [7.37, 8.02]) derives from mouse split-half controls, so absolute \u03c9 does not transfer across datasets or gene-selection schemes. Key parameters (top-200 DE genes, 2,000 HVGs, the +1 pseudo-count) are practical defaults rather than optimized values. (iii) Data and design: the TCGA analysis is limited to bulk RNA-seq resolution, its per-cancer permutation test holds the identity panel fixed (anti-conservative), and with five cancer types the TCGA results are exploratory; the brain atlas uses post-mortem tissue, and donor-level PMI and RNA-integrity covariates were unavailable, so regionally differential RNA degradation could masquerade as regional structure in k_n. (iv) Anchor visibility: \u03c9 is structurally insensitive to perturbations that move the housekeeping anchor itself\u2014in simulation, once 500 genes shifted, the ratio collapsed (AUC 0.05\u20130.13)\u2014and donor-paired permutation power vanishes beyond roughly 500 cells per group, bounding the practical operating window at approximately 50\u2013200 cells; the scDist results were obtained with a Python approximation of the R package and should be re-verified against the original implementation. (v) Multiple testing and cluster-aware inference: the class-level upper-tail tests and the pair-level lower-tail screen are separate families reported without cross-family joint correction; the block-shuffle null assumes libraries are otherwise exchangeable, so systematic library-level confounding would distort the null in ways the permutation cannot capture\u2014bounded empirically by the pseudo-region negative control (Supplementary Note 12)\u2014and B = 1,000 permutations bounds the resolvable P-value at 9.99 \u00d7 10\u207b\u2074, so the per-pair FDR outcome (minimum q = 0.520) is a statement about permutation resolution rather than evidence against any candidate. Full treatments of each limitation, with the supporting sensitivity analyses, are given in the Supplementary Information (Supplementary Notes 1\u201316).')'''))
R.append((r"p('Future directions include developmental biology",
 r'''p('Future directions include developmental biology, drug-response profiling, aging research, and evolutionary cell biology. The CKI Python package (v0.5.0) and all analysis notebooks are available at https://github.com/zhanglknt/CKI-cell-type-identification under the MIT License.')'''))
R.append((r"p('CKI adapts the baseline-normalization logic",
 r'''p('CKI adapts the baseline-normalization logic of Ka/Ks to single-cell transcriptomics, decomposing population divergence into a housekeeping baseline rate (k_n) and an identity-gene functional rate (k_f). Across simulation, calibration, cross-organ, pan-cancer, and brain-regional analyses, we showed that \u03c9 rankings carry reproducible biological signal while absolute \u03c9 values remain scheme- and dataset-specific, that statistical claims at atlas scale require nulls respecting the experimental design, and that the absence of FDR-significant candidates is itself an informative bound on what adult transcriptomes alone can support. CKI is released as an open-source Python package with a fully reproducible analysis pipeline, and we anticipate its use as an interpretable complement to standard distance metrics in comparative single-cell analyses.')'''))

nfail = 0
for prefix, newline in R:
    idx = [i for i, l in enumerate(lines) if l.startswith(prefix)]
    if len(idx) != 1:
        print('FAIL prefix not unique:', prefix[:60], len(idx)); nfail += 1; continue
    old = lines[idx[0]]
    lines[idx[0]] = newline
    print(f'OK L{idx[0]+1}: {len(old.split())} -> {len(newline.split())}')
if nfail:
    raise SystemExit(1)
io.open(P, 'w', encoding='utf-8', newline='\n').write('\n'.join(lines))
print('batch 9 written')
